import os
target_file = "/Users/pochoco/Desktop/원소주기율표/elements_data.js"
if os.path.exists(target_file):
    with open(target_file, "r", encoding="utf-8") as f:
        content = f.read()
    
    content = content.replace("const elementsData = ", "").replace(";", "").strip()
    elements = json.loads(content)
    
    for el in elements:
        z = el["num"]
        if z in data_more:
            el["desc"] = data_more[z]["desc"]
            el["use"] = data_more[z]["use"]
            el["fact"] = data_more[z]["fact"]

    with open(target_file, "w", encoding="utf-8") as f:
        f.write("const elementsData = ")
        json.dump(elements, f, ensure_ascii=False, indent=2)
        f.write(";")
    
    print("Updated ALL 118 elements with unique facts.")
else:
    print("File not found")
